"""Evidence report and verification verdict schemas."""

from enum import Enum
from typing import List, Optional
from pydantic import BaseModel, Field

from aero_code.schemas.patch import PatchProposal
from aero_code.schemas.research import TavilyCitation


class VerificationVerdict(str, Enum):
    """Verdict of the ProofLoop double-verification engine."""

    VERIFIED = "VERIFIED"
    FAILED = "FAILED"
    INCONCLUSIVE = "INCONCLUSIVE"


class EvidenceReport(BaseModel):
    """Cryptographically auditable evidence report generated by ProofLoop."""

    run_id: str
    repository: str = ""
    baseline_commit: str = ""
    patch_commit: str = ""
    model_used: str = ""
    citations: List[TavilyCitation] = Field(default_factory=list)
    patch: Optional[PatchProposal] = None
    baseline_test_passed: bool = False  # Did regression test fail on unpatched code? True if repro succeeded
    patched_test_passed: bool = False   # Did regression test pass on patched code?
    baseline_suite_passed: bool = False # Did existing test suite remain passing (zero regressions)?
    git_guard_passed: bool = False      # Did patch respect test and config immutability?
    verdict: VerificationVerdict
    execution_duration_ms: float = 0.0
    notes: str = ""
